// Import articles and stories
import exploreArticles from '@/content/explore/articles.js';
import cultureArticles from '@/content/culture/articles.js';
import stories from '@/content/stories/articles.js';

console.log('Explore Articles:', exploreArticles);
console.log('Culture Articles:', cultureArticles);
console.log('Stories:', stories);

const searchIndex = [];

// Combine articles and stories into a single index
exploreArticles.forEach((article) => {
  searchIndex.push({
    id: article.id,
    title: article.title,
    summary: article.summary,
    section: 'explore',
  });
});

cultureArticles.forEach((article) => {
  searchIndex.push({
    id: article.id,
    title: article.title,
    summary: article.summary,
    section: 'culture',
  });
});

stories.forEach((story) => {
  searchIndex.push({
    id: story.id,
    title: story.title,
    summary: story.summary,
    section: 'stories',
  });
});

export default searchIndex;